private <T, N> void doInit(final Closure<T> closure, final Class<N> delegateClass, final int resolveStrategy) {
  init(injector -> {
    Registry injectorBackedRegistry = Guice.registry(injector);
    N delegate = delegateClass.equals(Void.class) ? null : injector.getInstance(delegateClass);
    new ClosureInvoker<T, N>(closure).invoke(injectorBackedRegistry, delegate, resolveStrategy);
  });
}

