import com.google.common.util.concurrent.AbstractIdleService;
import org.jboss.netty.bootstrap.ServerBootstrap;
import org.jboss.netty.channel.Channel;
import org.jboss.netty.channel.ChannelFactory;
import org.jboss.netty.channel.ChannelPipelineFactory;
import org.jboss.netty.channel.group.ChannelGroup;
import org.ratpackframework.bootstrap.RatpackServer;
import org.ratpackframework.Handler;

import javax.inject.Inject;
import java.net.InetSocketAddress;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * A Netty-based RatpackServer implementation.
 */
public class NettyRatpackServer extends AbstractIdleService implements RatpackServer {

  private final Logger logger = Logger.getLogger(getClass().getName());

  /** The user-provided socket address that the server should bind to. */
  private final InetSocketAddress requestedAddress;
  private final ChannelFactory channelFactory;
  private final ChannelGroup channelGroup;
  private final Handler<RatpackServer> init;
  private final ChannelPipelineFactory channelPipelineFactory;

  /**
   * @param requestedAddress the requested socket address to bind to
   * @param channelFactory   the Netty channel factory
   * @param channelGroup     the group to track open channels
   * @param channelPipelineFactory the pipeline factory for new connections
   * @param init             the initialization handler
   */
  @Inject
  public NettyRatpackServer(
      InetSocketAddress requestedAddress,
      ChannelFactory channelFactory,
      ChannelGroup channelGroup,
      ChannelPipelineFactory channelPipelineFactory,
      Handler<RatpackServer> init
  ) {
    this.requestedAddress = requestedAddress;
    this.channelFactory = channelFactory;
    this.channelGroup = channelGroup;
    this.channelPipelineFactory = channelPipelineFactory;
    this.init = init;
  }

  @Override
  protected void startUp() {
    ServerBootstrap bootstrap = new ServerBootstrap(channelFactory);
    bootstrap.setPipelineFactory(channelPipelineFactory);
    bootstrap.setOption("child.tcpNoDelay", true);
    bootstrap.setOption("child.keepAlive", true);
    Channel channel = bootstrap.bind(requestedAddress);
    channelGroup.add(channel);

    init.handle(this);

    if (logger.isLoggable(Level.INFO)) {
      logger.info(String.format(
        "Ratpack started for http://%s:%s", getBindHost(), getBindPort()));
    }
  }

  @Override
  protected void shutDown() {
    channelGroup.close().awaitUninterruptibly();
    channelFactory.releaseExternalResources();
  }

  @Override
  public int getBindPort() {
    return requestedAddress.getPort();
  }

  @Override
  public String getBindHost() {
    return requestedAddress.getHostName();
  }

}

