public interface ByAcceptsResponder {

  /**
   * Terminal operation to assemble the response based on accepted types.
   */
  void build();

  /**
   * @deprecated use {@link #build()} instead.
   */
  @Deprecated
  default void send() {
    build();
  }
}

@Override
public void build() {
  if (first == null) {
    exchange.clientError(406);
    return;
  }
  List<String> types = new ArrayList<>(map.keySet());
  Collections.reverse(types);
  String winner = first;

  String acceptHeader = exchange.getRequest().getHeader(HttpHeaders.Names.ACCEPT);
  if (acceptHeader != null && !acceptHeader.isEmpty()) {
    winner = MimeParse.bestMatch(types, acceptHeader);
  }

  if (winner == null || winner.isEmpty()) {
    exchange.clientError(406);
  } else {
    exchange.getResponse().setHeader(HttpHeaders.Names.CONTENT_TYPE, winner);
    map.get(winner).run();
  }
}

