public static <T, R> R configureDelegateOnly(@DelegatesTo.Target T delegate, @DelegatesTo(strategy = Closure.DELEGATE_ONLY) Closure<R> configurer) {
  return configure(delegate, configurer, Closure.DELEGATE_ONLY);
}

public static <T, R> R configureDelegateFirst(@DelegatesTo.Target T delegate, @DelegatesTo(strategy = Closure.DELEGATE_FIRST) Closure<R> configurer) {
  return configure(delegate, configurer, Closure.DELEGATE_FIRST);
}

private static <T, R> R configure(T delegate, Closure<R> configurer, int resolveStrategy) {
  if (configurer == null) {
    return null;
  }
  @SuppressWarnings("unchecked")
  Closure<R> clone = (Closure<R>) configurer.clone();
  clone.setDelegate(delegate);
  clone.setResolveStrategy(resolveStrategy);
  if (clone.getMaximumNumberOfParameters() == 0) {
    return clone.call();
  } else {
    return clone.call(delegate);
  }
}

public static <T> Action<T> delegatingAction(@SuppressWarnings("UnusedParameters") Class<T> type, final Closure<?> configurer) {
  return new Action<T>() {
    public void execute(T delegate) {
      configureDelegateFirst(delegate, configurer);
    }
  };
}

